begin;create extension if not exists pgtap with schema extensions;select plan(14);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','a0000000-0000-0000-0000-000000000001','authenticated','authenticated','lease-a@example.test','',now(),'{}','{}',now(),now()),('00000000-0000-0000-0000-000000000000','a0000000-0000-0000-0000-000000000002','authenticated','authenticated','lease-b@example.test','',now(),'{}','{}',now(),now());
insert into public.organizations(id,public_id,name)values('a1000000-0000-0000-0000-000000000001','org_leaseaaaaaaaaaaa','Lease A'),('a1000000-0000-0000-0000-000000000002','org_leasebbbbbbbbbbb','Lease B');
insert into public.organization_memberships(id,organization_id,user_id,role,status)values('a2000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001','owner','active'),('a2000000-0000-0000-0000-000000000002','a1000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000002','owner','active');
insert into public.contacts(id,organization_id,created_by_membership_id,assigned_membership_id,first_name,last_name,primary_email,source,lifecycle_status,marketing_email_status)values('a3000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','Lease','Recipient','lease@example.test','Lease','nurture','opted-in');
set local role authenticated;select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000001',true);
insert into public.contact_lists(organization_id,created_by_membership_id,name)values('a1000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','Lease list');insert into public.contact_list_memberships(organization_id,list_id,contact_id,added_by_membership_id)values('a1000000-0000-0000-0000-000000000001',(select id from public.contact_lists where name='Lease list'),'a3000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001');
insert into public.marketing_campaigns(organization_id,created_by_membership_id,name,subject,sender_name,reply_to,audience_type,audience_public_id,status,content)values('a1000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','Lease campaign','Hello','Alex','alex@example.test','list',(select public_id from public.contact_lists where name='Lease list'),'ready','{"version":1,"heading":"Hi","body":"Body","ctaLabel":"","ctaUrl":"","footer":"Footer"}');
select lives_ok($$select public.confirm_campaign_send((select public_id from public.marketing_campaigns where name='Lease campaign'),'lease-test-key-0001',false)$$,'existing run created once');
select is((select count(*) from public.claim_campaign_recipients((select public_id from public.marketing_send_runs),1,'a4000000-0000-0000-0000-000000000001')),1::bigint,'pending recipient claimed');
select is((select count(*) from public.claim_campaign_recipients((select public_id from public.marketing_send_runs),1,'a4000000-0000-0000-0000-000000000002')),0::bigint,'a second concurrent worker cannot own an active lease');
reset role;update public.marketing_send_recipients set claimed_at=now()-interval '16 minutes';set local role authenticated;select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000001',true);
select is((select count(*) from public.claim_campaign_recipients((select public_id from public.marketing_send_runs),1,'a4000000-0000-0000-0000-000000000002')),1::bigint,'stale processing lease reclaimed atomically');
select is((select claim_token from public.marketing_send_recipients),'a4000000-0000-0000-0000-000000000002'::uuid,'reclaim assigns new owner token');
select throws_ok($$select public.complete_campaign_recipient((select public_id from public.marketing_send_recipients),'a4000000-0000-0000-0000-000000000001','accepted','old-owner-message',null)$$,'42501','Recipient claim is unavailable.','old owner cannot complete reclaimed work');
select lives_ok($$select public.complete_campaign_recipient((select public_id from public.marketing_send_recipients),'a4000000-0000-0000-0000-000000000002','accepted','current-owner-message',null)$$,'current owner completes work');
select is((select provider_message_id from public.marketing_send_recipients),'current-owner-message','current owner result persisted');
select is((select count(*) from public.marketing_send_runs),1::bigint,'recovery creates no new send run');
select is((select count(*) from public.marketing_send_recipients),1::bigint,'recovery creates no new recipient snapshot');
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.claim_campaign_recipients((select public_id from public.marketing_send_runs where organization_id='a1000000-0000-0000-0000-000000000001'),1,'a4000000-0000-0000-0000-000000000003')$$,'42501','Send run is unavailable.','tenant cannot claim another organization');
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000001',true);
select is((select count(*) from public.claim_campaign_recipients((select public_id from public.marketing_send_runs),1,'a4000000-0000-0000-0000-000000000003')),0::bigint,'completed recipient cannot be reclaimed');
select ok((select indexdef like '%status = ANY%' or indexdef like '%status IN%' from pg_indexes where schemaname='public' and indexname='marketing_recipients_claim_idx'),'lease claim index exists');
select ok(has_function_privilege('service_role','public.claim_campaign_recipients(text,integer,uuid)','execute'),'service-role worker can execute the bounded claim function');
select * from finish();rollback;
